  `reason` varchar(31) DEFAULT '',
  `notes` varchar(255) DEFAULT '',
  PRIMARY KEY (`void_id`),
  KEY `datevoided` (`date_voided`),
  KEY `pidenc` (`patient_id`,`encounter_id`)
